const organicResults = $input.first().json.organic_results || [];

function extractInstagramProfile(url) {
  const regex = /^https:\/\/(www\.)?instagram\.com\/([a-zA-Z0-9._-]+)\/?$/;
  const match = url.trim().match(regex);
  if (!match) return null;

  const username = match[2].toLowerCase();

  const blacklist = ['explore', 'p', 'reel', 'reels', 'tv', 'tags', 'stories', 'accounts', 'developer', 'directory', 'graphql'];

  if (blacklist.includes(username)) return null;

  return `https://www.instagram.com/${username}/`;
}

for (const item of organicResults) {
  const rawLink = (item.link || item.redirect_link || '').trim();
  const profile = extractInstagramProfile(rawLink);
  if (profile) {
    return [{ json: { instagram: profile } }];
  }
}

// Si no encuentra ninguno
return [{ json: { instagram: null } }];

const html = $input.first().json.data || "";

// Regex para capturar URLs de Instagram
const regex = /https:\/\/(www\.)?instagram\.com\/([a-zA-Z0-9._-]+)\/?/g;

const matches = [];
let match;

const blacklist = [
  'p', 'reel', 'explore', 'tv', 'startpage', 'about', 'developer', 'directory', 'graphql'
];

while ((match = regex.exec(html)) !== null) {
  const url = match[0];
  const username = match[2].toLowerCase();

  if (
    !blacklist.includes(username) &&
    !url.includes('/p/') &&
    !url.includes('/reel/') &&
    !url.includes('/explore/') &&
    !url.includes('/tv/')
  ) {
    const profileUrl = url.endsWith('/') ? url : url + '/';
    matches.push(profileUrl);
  }
}

// Elimina duplicados
const unique = [...new Set(matches)];

// Si no hay resultados devuelve null
if (unique.length === 0) {
  return [{ json: { instagram: null } }];
}

// Devuelve todos los perfiles encontrados, uno por item
return unique.map(link => ({ json: { instagram: link } }));

const organic = $input.first().json.organic || [];

function extractInstagramProfile(url) {
  // Match el patrón de perfil base: https://www.instagram.com/username/
  // Username puede tener letras, números, puntos, guiones bajos y guiones.
  const regex = /^https:\/\/(www\.)?instagram\.com\/([a-zA-Z0-9._-]+)\/?.*$/;
  const match = url.match(regex);
  if (!match) return null;

  const username = match[2].toLowerCase();

  // Lista negra de paths que no son perfiles
  const blacklist = ['explore', 'p', 'reel', 'reels', 'tv', 'tags', 'stories', 'accounts', 'developer', 'directory', 'graphql'];

  if (blacklist.includes(username)) return null;

  // Devuelve URL base del perfil
  return `https://www.instagram.com/${username}/`;
}

for (const item of organic) {
  const profile = extractInstagramProfile(item.link);
  if (profile) {
    return [{ json: { instagram: profile } }];
  }
}

// Si no encuentra ninguno
return [{ json: { instagram: null } }];

